package com.campuspulse.config;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import com.campuspulse.repository.*;import com.campuspulse.entity.*;import com.campuspulse.enums.Role;import java.util.*;
@Configuration public class SeedConfig{
@Bean CommandLineRunner seed(UserRepository users,DepartmentRepository departments,PasswordEncoder encoder,@Value("${app.admin.email:}") String email,@Value("${app.admin.password:}") String password){return args->{for(String n:List.of("IT Services","Maintenance","Housekeeping","Campus Security","General Administration")){if(departments.findByName(n).isEmpty()){Department d=new Department();d.name=n;departments.save(d);}}if(!email.isBlank()&&!password.isBlank()){if(password.length()<12)throw new IllegalStateException("ADMIN_PASSWORD must be 12+ characters");if(users.findByEmailIgnoreCase(email).isEmpty()){User a=new User();a.name="Campus Administrator";a.email=email.trim().toLowerCase();a.password=encoder.encode(password);a.role=Role.ADMIN;users.save(a);}}};}
}
